var words = "the quick brown fox jumped".split(" ");
var maxLength = 0;
for (var i = 0; i < words.length; i++) {
  if (words[i].length > maxLength) {
    maxLength = words[i].length;
  }
}
var longest = "";
for (var j = 0; j < words.length; j++) {
  if (words[j].length === maxLength) {
    longest = words[j];
    break;
  }
}
console.log(longest);

